import unittest
from candidate import how_many_times

class TestHowManyTimes(unittest.TestCase):
    def test_empty_string(self):
        self.assertEqual(how_many_times("", "a"), 0)

    def test_empty_substring(self):
        self.assertEqual(how_many_times("abc", ""), 3)

    def test_single_char_substring(self):
        self.assertEqual(how_many_times("aaa", "a"), 3)

    def test_overlapping_substrings(self):
        self.assertEqual(how_many_times("aaaa", "aa"), 3)

    def test_no_overlap(self):
        self.assertEqual(how_many_times("ababab", "ab"), 2)

    def test_case_sensitivity(self):
        self.assertEqual(how_many_times("AaAa", "aA"), 2)

    def test_substring_longer_than_string(self):
        self.assertEqual(how_many_times("abc", "abcd"), 0)

    def test_substring_equal_to_string(self):
        self.assertEqual(how_many_times("abc", "abc"), 1)

    def test_substring_not_found(self):
        self.assertEqual(how_many_times("abc", "xyz"), 0)

    def test_multiple_occurrences_with_overlap(self):
        self.assertEqual(how_many_times("abababab", "aba"), 3)

    def test_substring_at_start(self):
        self.assertEqual(how_many_times("ababab", "aba"), 2)

    def test_substring_at_end(self):
        self.assertEqual(how_many_times("ababab", "aba"), 2)

    def test_substring_with_spaces(self):
        self.assertEqual(how_many_times("hello hello", "llo "), 1)

    def test_none_values(self):
        with self.assertRaises(TypeError):
            how_many_times(None, "abc")
        with self.assertRaises(TypeError):
            how_many_times("abc", None)

    def test_non_string_inputs(self):
        with self.assertRaises(TypeError):
            how_many_times(123, "abc")
        with self.assertRaises(TypeError):
            how_many_times("abc", 123)

    def test_substring_with_special_characters(self):
        self.assertEqual(how_many_times("a@a@a", "@a"), 2)

    def test_boundary_case_empty_substring(self):
        self.assertEqual(how_many_times("", ""), 1)

    def test_boundary_case_single_char_in_string(self):
        self.assertEqual(how_many_times("a", "a"), 1)

    def test_boundary_case_single_char_in_substring(self):
        self.assertEqual(how_many_times("aa", "a"), 2)
